Class Tarjeta
  Private Define saldo As Integer;

  Method Constructor(inicial As Integer)
    This.saldo <- 0;
    If inicial > 0 Then
      This.saldo <- inicial;
    EndIf
  EndMethod

  Method Cobrar(monto As Integer) As Boolean
    If monto <= 0 Or monto > This.saldo Then
      Return False;
    EndIf
    This.saldo <- This.saldo - monto;
    Return True;
  EndMethod

  Method Cargar(monto As Integer) As Boolean
    If monto <= 0 Then
      Return False;
    EndIf
    This.saldo <- This.saldo + monto;
    Return True;
  EndMethod

  Method Saldo() As Integer
    Return This.saldo;
  EndMethod
EndClass

Algorithm Pruebas
  Define inicial, cobro, carga As Integer;
  Read inicial;
  Read cobro;
  Read carga;
  Define tarjeta As Tarjeta <- New Tarjeta(inicial);
  Write tarjeta.Cobrar(cobro), " ", tarjeta.Cargar(carga), " ", tarjeta.Saldo();
EndAlgorithm

